180	<div id="prb" class="blk hide"><h2>Pull request</h2><div id="diff" class="surf diff mono"></div><details class="pr surf" id="prd"><summary><span>PR description</span><button type="button" class="ghost" id="cpb">Copy</button></summary><pre id="prt"></pre></details></div>
