189	<script>
190	(function(){
191	"use strict";
192	var $=function(i){return document.getElementById(i)};
193	var RM=window.matchMedia&&matchMedia("(prefers-reduced-motion: reduce)").matches;
194	var STEP=RM?0:350,PAUSE=RM?0:500,tok=0,data=null;
195	function el(t,c,x){var e=document.createElement(t);if(c)e.className=c;if(x!=null)e.textContent=x;return e}
196	function show(i,on){$(i).classList.toggle("hide",!on)}
197	function sleep(ms){return new Promise(function(r){ms?setTimeout(r,ms):r()})}
198	function fmt(s){s=Math.round(+s||0);if(s<60)return s+"s";return Math.floor(s/60)+"m "+(s%60)+"s"}
199	function dur(s){s=+s||0;return s<10?s.toFixed(1)+"s":fmt(s)}
200	function copy(btn,text){var o=btn.textContent;(navigator.clipboard?navigator.clipboard.writeText(text):Promise.reject()).then(function(){btn.textContent="Copied"},function(){btn.textContent="Press Ctrl+C"});setTimeout(function(){btn.textContent=o},2000)}
201	function safeUrl(u){return typeof u==="string"&&/^https?:\/\//i.test(u)}
202	
203	/* decode */
204	function b64u(s){s=s.replace(/-/g,"+").replace(/_/g,"/");while(s.length%4)s+="=";var b=atob(s),u=new Uint8Array(b.length);for(var i=0;i<b.length;i++)u[i]=b.charCodeAt(i);return u}
205	function decode(raw){
206	  var c=String(raw||"").trim(),m=c.indexOf("#r=");if(m>=0)c=c.slice(m+3);c=c.replace(/\s+/g,"");
207	  if(!c)return Promise.reject(new Error("Paste a share code first."));
208	  if(typeof DecompressionStream==="undefined")return Promise.reject(new Error("This browser cannot decompress the code. Use a current Chrome, Safari or Firefox."));
209	  var bytes;try{bytes=b64u(c)}catch(e){return Promise.reject(new Error("That is not a share code. It has characters a code never holds."))}
210	  return new Response(new Blob([bytes]).stream().pipeThrough(new DecompressionStream("gzip"))).text().then(function(t){
211	    var o;try{o=JSON.parse(t)}catch(e){throw new Error("The code decoded but its content is not a run.")}
212	    if(!o||typeof o!=="object"||!Array.isArray(o.steps))throw new Error("The code decoded but holds no steps.");
213	    return o;
214	  },function(){throw new Error("The code is damaged or cut short. Copy it again from your terminal.")});
215	}
