233	  function add(l,v){var s=el("span");s.appendChild(document.createTextNode(l+" "));s.appendChild(el("b",null,v));M.appendChild(s)}
234	  if(d.target)add("Target",d.target);
235	  if(d.time_to_first_success_s!=null)add("Time to first success",fmt(d.time_to_first_success_s));
236	  if(d.tool_calls!=null)add("Tool calls",String(d.tool_calls));
237	  if(d.cost_usd!=null)add("Cost","$"+(+d.cost_usd).toFixed(2)+" list price, not billed");
238	  var S=$("src");S.textContent="";
