240	}
241	function buildSteps(d){
242	  var U=$("steps");U.textContent="";var rows=[];
243	  d.steps.forEach(function(s){
244	    var li=el("li","pend"),tail=typeof s.error_tail==="string"&&s.error_tail?s.error_tail:"";
245	    var row=el(tail?"summary":"div","sr");
246	    row.appendChild(el("span","ic","·"));
247	    row.appendChild(el("span","cmd mono",s.command||""));
248	    row.appendChild(el("span","mt"));
249	    row.appendChild(el("span","int",s.intent||(s.command||"")));
250	    var host=li;
251	    if(tail){host=el("details");li.appendChild(host);host.appendChild(row);host.appendChild(el("pre","tail mono",tail))}else li.appendChild(row);
252	    U.appendChild(li);rows.push({li:li,s:s,d:host,row:row});
253	  });
254	  return rows;
255	}
256	function fillRow(r){
257	  var s=r.s,st=s.status||"pending",ic=r.row.children[0],mt=r.row.children[2];
258	  r.li.className=st==="passed"?"ok":st==="skipped"?"sk":st==="pending"?"pend":"no";
259	  ic.textContent=st==="passed"?"✓":st==="skipped"?"-":st==="pending"?"·":"✗";
260	  mt.textContent="";
261	  if(st==="skipped"){mt.textContent=s.skip_reason||"skipped"}
262	  else{
263	    if(s.attempts>1){mt.appendChild(el("b",null,s.attempts+" attempts"));mt.appendChild(document.createTextNode(" · "))}
264	    mt.appendChild(document.createTextNode(dur(s.duration_s)));
265	  }
266	  if(r.d.tagName==="DETAILS"&&st!=="passed")r.d.open=true;
267	}
268	function renderFixes(d){
269	  var F=$("fixes");F.textContent="";
270	  var ps=Array.isArray(d.patches)?d.patches:[];
271	  ps.forEach(function(p){
272	    var c=el("div","fx surf");
273	    c.appendChild(el("h3",null,"Step "+p.step_id+(p.failure_class?": "+String(p.failure_class).replace("_"," "):"")));
